/**
 * The picture the reading pane shows before anyone chooses their own.
 *
 * It is a data URL rather than a file in `public/`, because the two hosts
 * serve static files differently and a `.jpg` import gives Vite a string and
 * Next an object. A string in a module is the one thing both agree on.
 *
 * Nothing imports this at the top level. `MailRestPanel` loads it with a
 * dynamic import, and only while no picture has been chosen — so it is a
 * chunk of its own, and a reader who picked their own photo never fetches it.
 *
 * Generated by `apps/mail/scripts/encode-rest-default.mjs`. Do not edit by
 * hand: the script also strips EXIF, and a phone photo's EXIF holds the GPS
 * position it was taken at, which would otherwise ship to everyone who
 * installs the app.
 *
 * 1600x1200, 188 kB.
 */

export const REST_DEFAULT_IMAGE =
  "data:image/jpeg;base64,";
